{
 "command": "make test-fast 2>&1 | tail -40",
 "description": "Run fast test suite"
}

{
 "command": "cd services/notifier && python -m pytest --import-mode=importlib tests 2>&1 | tail -30",
 "description": "Run notifier tests separately"
}

{
 "pattern": "LEDGERLINE_FX_FIXTURES",
 "path": "/tmp/mte-mt-sandbox-region-8nu23bkg/ledgerline",
 "output_mode": "content"
}

{
 "mode": "filter",
 "query": "FX fixtures"
}

{
 "command": "cd /tmp/mte-mt-sandbox-region-8nu23bkg/ledgerline && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30",
 "description": "Rerun fast tests with FX fixtures env var"
}

{
 "command": "ls -la tests/fixtures tests/fixtures/fx 2>&1; sed -n 1,30p docs/testing.md; git log --oneline --stat -3 | head -30",
 "description": "Inspect fixtures dir and testing docs"
}

{
 "command": "python scripts/gen_fx_fixtures.py 2>&1 | tail -10 && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30; git status --short",
 "description": "Generate FX fixtures and rerun fast tests"
}

{
 "mode": "filter",
 "query": "PSP sandbox region"
}
